// Ensures the generated billing seam files exist before anything tries to
// build.
//
// Each entry is (generated file, checked-in stub, private implementation). The
// generated files are gitignored, and what lands there depends on what the
// checkout actually carries:
//
//   - a `_private/` implementation present  -> write a re-export pointing at it
//   - nothing but the stub                  -> copy the stub
//   - the file already exists               -> leave it alone
//
// The first branch is the one that matters. `_private/` is tracked in the
// internal repository and stripped from the public mirror by
// scripts/publish-github.sh, but the one-line re-export that reaches it never
// was — so every CI checkout used to fall through to the stub and ship a build
// that cheerfully told users it could not sell them anything. Deriving the
// re-export instead of requiring someone to have written it by hand on their
// laptop is what keeps the release honest.
import { copyFileSync, existsSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");

const seams = [
  {
    target: join(root, "convex", "billing", "provider.ts"),
    stub: join(root, "convex", "billing", "provider.stub.ts"),
    private: join(root, "convex", "billing", "_private", "stripeProvider.ts"),
    reexport: 'export { provider } from "./_private/stripeProvider";\n',
  },
  {
    target: join(
      root,
      "apps",
      "mobile",
      "src",
      "components",
      "billing",
      "index.tsx",
    ),
    stub: join(
      root,
      "apps",
      "mobile",
      "src",
      "components",
      "billing",
      "index.stub.tsx",
    ),
    private: join(
      root,
      "apps",
      "mobile",
      "src",
      "components",
      "billing",
      "_private",
      "payment-ui.tsx",
    ),
    reexport: `export {
  AiAccessRequiredModal,
  BillingSubscriptionPanel,
  CheckoutResultOverlay,
} from "./_private/payment-ui"
`,
  },
];

const BANNER = `// Generated by scripts/ensure-billing-provider.mjs. Gitignored: delete it and
// the next install writes it again. Edit the module it points at, not this.
`;

for (const { target, stub, private: privateImpl, reexport } of seams) {
  if (existsSync(target)) continue;

  if (existsSync(privateImpl)) {
    writeFileSync(target, BANNER + reexport);
    console.log(`billing: wired ${target} to the private implementation`);
    continue;
  }

  copyFileSync(stub, target);
  console.log(`billing: no provider found, installed the stub (${target})`);
}
